            return Dir(path=str(path.resolve()), url=str(path))
        else:
            # Handle other paths (e.g., project paths)
            # For simplicity, we'll just return the input path as is
            return Dir(path=dir_path, url=None)

    else:
        # Handle other types (e.g., None)
        return None
