    See this ChatGPT translation of mm code from Solr's Java code for parsing this
    https://chat.openai.com/share/76642aec-7e05-420f-a53a-83b8e2eea8fb

    Parameters
    ----------
    num_clauses : int
    spec : str

    Returns
    -------
    int : the number of clauses that must match
    """
    spec = spec.strip()

    if '<' in spec:
        conditional_part, _ = spec.split('<', 1)
        conditional_value = checked_parse_int(conditional_part)
        return max(0, num_clauses - conditional_value)
    else:
        # Check if the spec is a percentage
        if spec.endswith('%'):
            # Convert the spec to an integer and calculate the percentage of the total number of clauses
            spec_value = checked_parse_int(spec[:-1])
            return max(0, num_clauses * spec_value // 100)
        else:
            # Convert the spec to an integer and return it as the minimum number of clauses that must match
            return checked_parse_int(spec)
